function clone(x){return JSON.parse(JSON.stringify(x));}
function load(){try{const v=JSON.parse(localStorage.getItem(KEY)||'null');if(v&&Array.isArray(v.concepts))return v;}catch(e){}return {concepts:clone(examples)};}
let state=load();let filter='All';let q='';let sphereInstance=null;let modalConceptId=null;
let ambientInstance=null; let introTimer=null;
let localStorageWarned=false;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch(e){if(!localStorageWarned){localStorageWarned=true;toast('Local saving is blocked here. Changes will stay in this tab; download your brief before leaving.');}return true;}}
function escapeHTML(s=''){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function uid(){return 'id-'+Math.random().toString(36).slice(2,9);}
