function logo(){return `<span class="brand" aria-label="COLLAB">COL<span>LAB</span><sup>™</sup></span>`;}
function statusClass(s){return String(s).toLowerCase().replace(/\s+/g,'-');}
function iconFor(t){return ({'Social ad':'◎','Email':'✉','Search':'⌕','Landing page':'▤','Donation form':'♡','Thank-you page':'✓','Follow-up email':'↗','Other':'◇'})[t]||'◇';}
function safeColor(i){return ['blue','sand','slate','mint'][i%4];}
function colorStatus(s){return `<span class="card-status ${statusClass(s)}">${escapeHTML(s)}</span>`;}
function readiness(c){return [!!(c.title&&c.title!=='Untitled concept'&&c.summary),!!(c.audience?.length&&c.insight),!!(c.assets?.length||c.creativeNotes),!!(c.headline&&c.bodyCopy),!!c.studioTouched,!!(c.journey?.length>=2),!!(c.outcomes?.primary)].map(Boolean);}
function share(c){const r=readiness(c);return Math.round(100*r.filter(Boolean).length/r.length);}
function route(path){if(location.hash==='#'+path)render();else location.hash=path;}
function create(){let c={id:uid(),title:'Untitled concept',subtitle:'',category:'Appeal',sparked:'',summary:'',objective:'',audience:[],insight:'',motivation:'',action:'',creativeNotes:'',assetLink:'',assets:[],colourChoices:[],customColour:'#008dc7',fontPreference:'No preference',styleKeywords:'',thingsToAvoid:'',createdBy:userName||'Anonymous',headline:'',bodyCopy:'',cta:'',proof:'',journey:[{id:uid(),type:'Social ad',x:35,y:115,note:'How will people discover this campaign?'},{id:uid(),type:'Landing page',x:250,y:115,note:'What should they understand?'},{id:uid(),type:'Donation form',x:465,y:115,note:'What should they do?'}],outcomes:{primary:'',target:'',budget:'',launch:'',secondary:''},status:'Draft',notes:'',comments:[],updatedAt:now(),demo:false};state.concepts.unshift(c);persist();return c;}
