function sidebar(active){return `<aside class="app-sidebar"><a href="#/home">${logo()}</a><div class="nav-caption">Workspace</div><nav class="app-nav" aria-label="Workspace navigation"><a class="${active==='workspace'?'current':''}" href="#/workspace"><span class="nav-icon">▦</span>Overview</a><a class="${active==='concept'?'current':''}" href="#/workspace" data-action="concepts"><span class="nav-icon">◇</span>Concepts</a><a href="#/workspace" data-action="new"><span class="nav-icon">＋</span>New concept</a><a class="${active==='review'?'current':''}" href="#/review"><span class="nav-icon">✓</span>Reviews</a></nav><div class="app-side-bottom"><span class="micro">RFDS / SA·NT</span><p>Less crossed wires. More useful ideas. Lee approves.</p><a href="#/home" style="font-size:11px;color:#008dc7">← Back to site</a></div></aside>`;}
function shell(title,body,active='workspace'){return `<div class="app-shell">${sidebar(active)}<main class="app-main"><header class="app-topbar"><div class="topbar-left"><span>COLLAB</span><span>/</span><b>${escapeHTML(title)}</b></div><div class="topbar-right"><button type="button" class="topbar-name" data-action="change-name">${userName?`Hi, ${person()}`:`Set your name`} ↗</button><span class="avatar">${escapeHTML((userName||"RF").slice(0,2).toUpperCase())}</span></div></header>${body}</main></div>`;}
function projectCard(c,i){return `<article class="project-card" tabindex="0" role="button" data-open="${escapeHTML(c.id)}" aria-label="Open ${escapeHTML(c.title)}"><div class="project-art ${safeColor(i)}"><span class="art-type">${escapeHTML(c.category.toUpperCase())}</span><span class="art-shape"></span><span class="art-symbol">${escapeHTML(c.title.split(' ').slice(0,2).join(' '))}</span></div><div class="project-card-body">${colorStatus(c.status)}<h3>${escapeHTML(c.title)}</h3><p>${escapeHTML(c.subtitle||c.summary||'A new fundraising concept to shape and share.')}</p><div class="project-card-foot"><span>${c.demo?'Example concept':'Your concept'}</span><span>Updated ${fmt(c.updatedAt)} ↗</span></div></div></article>`;}
function dashboard(){let concepts=state.concepts.filter(c=>(filter==='All'||c.status===filter)&&(c.title+' '+c.subtitle+' '+c.category).toLowerCase().includes(q.toLowerCase()));const counts={all:state.concepts.length,drafts:state.concepts.filter(x=>x.status==='Draft').length,review:state.concepts.filter(x=>x.status==='In review').length,approved:state.concepts.filter(x=>x.status==='Approved').length};return shell('Overview',`<div class="app-page"><div class="page-intro"><div><span class="micro">THE WORKSPACE / OVERVIEW</span><h1>Your next big idea, ${person()}.</h1><p>Hi ${person()}. This is where your fundraising ideas stop hiding in email threads and start making sense to Lee.</p></div><button class="btn dark" data-action="new">New concept <span>↗</span></button></div><section class="stats-grid"><div class="stat-card"><span class="micro">All concepts</span><div class="stat-bottom"><span class="number">${counts.all.toString().padStart(2,'0')}</span><b>↗</b></div></div><div class="stat-card"><span class="micro">In progress</span><div class="stat-bottom"><span class="number">${counts.drafts.toString().padStart(2,'0')}</span><b>◇</b></div></div><div class="stat-card"><span class="micro">In review</span><div class="stat-bottom"><span class="number">${counts.review.toString().padStart(2,'0')}</span><b>◎</b></div></div><div class="stat-card"><span class="micro">Approved</span><div class="stat-bottom"><span class="number">${counts.approved.toString().padStart(2,'0')}</span><b>✓</b></div></div></section><div class="studio-promo"><span>◉ &nbsp;THE STUDIO IS OPEN</span><div><h2>Ads. Emails. Journeys. One clear pitch.</h2><p>Build a campaign concept across channels, then let Lee see the whole story in one place.</p></div><button class="btn dark small" data-action="open-studio">Enter Campaign Studio ↗</button></div><div class="section-subhead"><h2>Concept library</h2><span class="micro">YOUR IDEAS, IN ONE PLACE</span></div><div class="filter-row">${['All','Draft','In review','Changes requested','Approved'].map(f=>`<button class="filter ${filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}<input id="concept-search" class="search-input" type="search" placeholder="Search concepts…" value="${escapeHTML(q)}" aria-label="Search concepts" /></div>${concepts.length?`<div class="project-grid">${concepts.map(projectCard).join('')}</div>`:`<div class="empty-box"><h3>Nothing here yet.</h3><p>Try a different filter or create a new concept.</p><button class="btn dark small" data-action="new">Start a concept ↗</button></div>`}<p class="helper" style="margin-top:24px">Example entries are supplied to demonstrate the experience. All edits are saved only in this browser.</p></div>`,'workspace');}
function v(c,path){return path.split('.').reduce((o,k)=>o?.[k],c)??'';}
function field(c,label,path,placeholder='',kind='input',help='',wide=false){const value=escapeHTML(v(c,path));const html=kind==='textarea'?`<textarea class="form-field" data-field="${path}" placeholder="${escapeHTML(placeholder)}">${value}</textarea>`:kind==='select'?`<select class="form-field" data-field="${path}">${placeholder.split('|').map(x=>`<option ${v(c,path)===x?'selected':''}>${escapeHTML(x)}</option>`).join('')}</select>`:`<input class="form-field" data-field="${path}" type="text" value="${value}" placeholder="${escapeHTML(placeholder)}" />`;return `<div class="form-group ${wide?'wide':''}"><label>${escapeHTML(label)}</label>${html}${help?`<small>${escapeHTML(help)}</small>`:''}</div>`;}
