for(let i=0;i<240;i++){let p=pts[Math.floor(rand()*pts.length)];pts.push({...p,x:p.x*(1.05+rand()*.18),y:p.y*(1.05+rand()*.18),z:p.z*(1.05+rand()*.18),alpha:p.alpha*.7,type:rand()});}
