  const p=pts[i];let x=p.x*cb+p.z*sb;let z=-p.x*sb+p.z*cb;let y=p.y*ca-z*sa;z=p.y*sa+z*ca;
  const depth=2.65/(2.65-z*.35);let xx=cx+x*radius*depth,yy=cy+y*radius*depth;
