 let w=0,h=0,dpr=1,last=0,frame=0,raf=0;
 let seed=83614;function random(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}
 const dots=Array.from({length:170},()=>({x:random(),y:random(),v:.000006+random()*.000018,scale:1+random()*2.2,kind:random(),phase:random()*6.283}));
 function resize(){w=innerWidth;h=innerHeight;dpr=Math.min(devicePixelRatio||1,1.4);canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);}
